begin;
create table if not exists public.mme_org_departments(department_id uuid primary key default gen_random_uuid(),department_code text not null unique,department_name text not null,parent_department_id uuid references public.mme_org_departments(department_id),department_head_auth_user_id uuid,entity_id uuid references public.mme_financial_reporting_entities(entity_id),status text not null default 'active' check(status in('active','inactive')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.mme_org_positions(position_id uuid primary key default gen_random_uuid(),position_code text not null unique,position_title text not null,department_id uuid not null references public.mme_org_departments(department_id),reports_to_position_id uuid references public.mme_org_positions(position_id),employment_type text not null default 'full_time' check(employment_type in('full_time','part_time','contract','temporary','seasonal')),authorized_headcount integer not null default 1 check(authorized_headcount>=0),salary_min numeric(14,2),salary_max numeric(14,2),position_status text not null default 'active' check(position_status in('active','frozen','retired')),created_at timestamptz not null default now(),check(salary_min is null or salary_min>=0),check(salary_max is null or salary_max>=0),check(salary_min is null or salary_max is null or salary_max>=salary_min));
create table if not exists public.mme_workforce_assignments(assignment_id uuid primary key default gen_random_uuid(),employee_auth_user_id uuid not null,position_id uuid not null references public.mme_org_positions(position_id),department_id uuid not null references public.mme_org_departments(department_id),manager_auth_user_id uuid,employment_status text not null default 'pending' check(employment_status in('pending','active','leave','suspended','terminated')),start_date date not null,end_date date,fte numeric(4,2) not null default 1 check(fte>0 and fte<=1),work_location text,created_at timestamptz not null default now(),check(end_date is null or end_date>=start_date));
create unique index if not exists mme_workforce_one_active_assignment_idx on public.mme_workforce_assignments(employee_auth_user_id) where employment_status in('pending','active','leave','suspended');
create index if not exists mme_workforce_department_idx on public.mme_workforce_assignments(department_id,employment_status);
create table if not exists public.mme_workforce_lifecycle_events(event_id uuid primary key default gen_random_uuid(),employee_auth_user_id uuid not null,event_type text not null check(event_type in('onboarding_started','activated','department_changed','position_changed','leave_started','leave_ended','suspended','terminated','rehired')),effective_date date not null,notes text,recorded_by_auth_user_id uuid not null,created_at timestamptz not null default now());
create table if not exists public.mme_workforce_capacity_plans(plan_id uuid primary key default gen_random_uuid(),department_id uuid not null references public.mme_org_departments(department_id),period_start date not null,period_end date not null,required_fte numeric(8,2) not null check(required_fte>=0),planned_fte numeric(8,2) not null check(planned_fte>=0),assumptions text,created_by_auth_user_id uuid not null,created_at timestamptz not null default now(),check(period_end>=period_start));
create table if not exists public.mme_workforce_succession_plans(succession_id uuid primary key default gen_random_uuid(),position_id uuid not null references public.mme_org_positions(position_id),criticality text not null check(criticality in('low','medium','high','critical')),readiness text not null check(readiness in('ready_now','under_1_year','one_to_three_years','no_successor')),successor_auth_user_id uuid,development_actions text,review_due_date date,owner_auth_user_id uuid not null,created_by_auth_user_id uuid not null,created_at timestamptz not null default now());
create table if not exists public.mme_workforce_performance_snapshots(snapshot_id uuid primary key default gen_random_uuid(),department_id uuid not null references public.mme_org_departments(department_id),period_start date not null,period_end date not null,metric_code text not null,metric_value numeric(16,4) not null,unit text not null,source_reference text,recorded_by_auth_user_id uuid not null,created_at timestamptz not null default now(),check(period_end>=period_start));
create index if not exists mme_workforce_performance_period_idx on public.mme_workforce_performance_snapshots(department_id,period_end desc);
do $$declare t text;begin foreach t in array array['mme_org_departments','mme_org_positions','mme_workforce_assignments','mme_workforce_lifecycle_events','mme_workforce_capacity_plans','mme_workforce_succession_plans','mme_workforce_performance_snapshots'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end$$;
commit;